data.minimal_example:
final choice = await showPopover<String>(
  context: context,
  width: 160,
  height: 112,
  bodyBuilder: (context) => Material(
    type: MaterialType.transparency,
    child: Column(
      children: [
        for (final item in ['Copy', 'Share'])
          ListTile(
            title: Text(item),
            onTap: () => Navigator.pop(context, item),
          ),
      ],
    ),
  ),
);
